<!--
  Dropdown pilihan custom (pengganti <select> native yang tampilannya polos &
  daftar opsinya mengikuti OS). Panel opsi di-Teleport ke body + diposisikan
  fixed dari rect tombol → tidak ter-clip di dalam container ber-overflow/scroll
  (mis. panel filter list & form detail). Dipakai konsisten di seluruh portal.

  Props:
    modelValue  : nilai terpilih (string|number)
    options     : array of string ATAU { value, label }
    placeholder : teks saat belum ada pilihan
    disabled    : nonaktif
    clearable   : tampilkan opsi "Kosongkan" untuk reset ke ''
    btnClass    : kelas tambahan untuk tombol (mengikuti gaya field pemanggil)
    optionClass : kelas tambahan untuk opsi di dalam panel (mis. 'text-xs')
-->
<template>
	<div ref="root" class="relative">
		<button
			type="button"
			:disabled="disabled"
			:class="['flex w-full items-center justify-between gap-2 text-left', btnClass]"
			@click="toggle"
		>
			<span class="min-w-0 truncate" :class="hasValue ? '' : 'text-ui-ink-gray-400'">
				{{ displayLabel }}
			</span>
			<svg
				xmlns="http://www.w3.org/2000/svg"
				viewBox="0 0 24 24"
				class="h-4 w-4 shrink-0 text-ui-ink-gray-400 transition-transform duration-200"
				:class="{ 'rotate-180': open }"
				fill="none"
				stroke="currentColor"
				stroke-width="2"
				stroke-linecap="round"
				stroke-linejoin="round"
			>
				<path d="m6 9 6 6 6-6" />
			</svg>
		</button>

		<Teleport to="body">
			<div v-if="open" class="fixed inset-0 z-[65]" @click="close" />
			<transition
				enter-active-class="transition duration-150 ease-out"
				enter-from-class="opacity-0 -translate-y-1"
				enter-to-class="opacity-100 translate-y-0"
			>
				<div
					v-if="open"
					class="fixed z-[70] overflow-hidden rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-xl ring-1 ring-black/5"
					:style="menuStyle"
				>
					<div class="max-h-64 overflow-y-auto p-1">
						<button
							v-if="clearable && hasValue"
							type="button"
							:class="[
								'flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-ui-ink-gray-400 transition hover:bg-ui-surface-gray-50',
								optionClass,
							]"
							@click="pick({ value: '', label: '' })"
						>
							<svg
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-4 w-4 shrink-0"
								fill="none"
								stroke="currentColor"
								stroke-width="2"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="M18 6 6 18" />
								<path d="m6 6 12 12" />
							</svg>
							Kosongkan
						</button>
						<button
							v-for="opt in normalized"
							:key="String(opt.value)"
							type="button"
							:class="[
								'flex w-full items-center justify-between gap-2 rounded-lg px-3 py-2 text-left text-sm transition',
								isSel(opt)
									? 'bg-ui-surface-gray-100 font-medium text-ui-ink-gray-900'
									: 'text-ui-ink-gray-700 hover:bg-ui-surface-gray-50',
								optionClass,
							]"
							@click="pick(opt)"
						>
							<span class="min-w-0 truncate">{{ opt.label }}</span>
							<svg
								v-if="isSel(opt)"
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-4 w-4 shrink-0 text-ui-ink-gray-700"
								fill="none"
								stroke="currentColor"
								stroke-width="2.5"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="M20 6 9 17l-5-5" />
							</svg>
						</button>
						<p
							v-if="!normalized.length"
							:class="['px-3 py-2 text-sm text-ui-ink-gray-400', optionClass]"
						>
							Tidak ada pilihan
						</p>
					</div>
				</div>
			</transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, ref } from 'vue'

const props = defineProps({
	modelValue: { type: [String, Number], default: '' },
	options: { type: Array, default: () => [] },
	placeholder: { type: String, default: 'Pilih…' },
	disabled: { type: Boolean, default: false },
	clearable: { type: Boolean, default: false },
	btnClass: { type: [String, Array, Object], default: '' },
	// Kelas tambahan untuk tiap opsi di dalam panel (mis. 'text-xs' agar sama
	// dengan ukuran font field pemanggil). Ditaruh setelah kelas dasar → menang.
	optionClass: { type: [String, Array, Object], default: '' },
})
const emit = defineEmits(['update:modelValue', 'change'])

const open = ref(false)
const root = ref(null)
const menuStyle = ref({})

// Normalisasi opsi → { value, label }; buang opsi kosong (placeholder ditangani sendiri).
const normalized = computed(() =>
	(props.options || [])
		.map((o) =>
			o != null && typeof o === 'object'
				? { value: o.value, label: o.label ?? String(o.value) }
				: { value: o, label: String(o) }
		)
		.filter((o) => o.value !== '' && o.value != null)
)
const hasValue = computed(() => props.modelValue !== '' && props.modelValue != null)
const displayLabel = computed(() => {
	const cur = normalized.value.find((o) => String(o.value) === String(props.modelValue))
	return cur ? cur.label : props.placeholder
})
function isSel(opt) {
	return String(opt.value) === String(props.modelValue)
}

// Posisikan panel: di bawah tombol; flip ke atas kalau ruang bawah sempit.
// Lebar menu = lebar tombol, tapi minimal 12rem supaya teks opsi tetap terbaca
// walau tombolnya sempit (mis. di panel filter); lalu dijaga tidak keluar layar.
function position() {
	const el = root.value
	if (!el) return
	const r = el.getBoundingClientRect()
	const vw = window.innerWidth
	const vh = window.innerHeight
	const below = vh - r.bottom
	const w = Math.min(Math.max(r.width, 192), vw - 16)
	let left = r.left
	if (left + w > vw - 8) left = Math.max(8, vw - w - 8)
	const style = { left: `${left}px`, width: `${w}px` }
	if (below < 260 && r.top > below) {
		style.bottom = `${vh - r.top + 6}px`
	} else {
		style.top = `${r.bottom + 6}px`
	}
	menuStyle.value = style
}
async function toggle() {
	if (props.disabled) return
	if (open.value) {
		close()
		return
	}
	open.value = true
	await nextTick()
	position()
}
function close() {
	open.value = false
}
function pick(opt) {
	emit('update:modelValue', opt.value)
	emit('change', opt.value)
	close()
}

// Reposisi saat scroll/resize supaya panel tetap menempel di tombol.
function onReflow() {
	if (open.value) position()
}
window.addEventListener('scroll', onReflow, true)
window.addEventListener('resize', onReflow)
onBeforeUnmount(() => {
	window.removeEventListener('scroll', onReflow, true)
	window.removeEventListener('resize', onReflow)
})
</script>
